import{_ as a,o as s,c as n,a6 as t}from"./chunks/framework.uNNoBQt2.js";const g=JSON.parse('{"title":"Dependabot maintenance","description":"","frontmatter":{},"headers":[],"relativePath":"dependabot-maintenance.md","filePath":"dependabot-maintenance.md"}'),i={name:"dependabot-maintenance.md"};function o(r,e,d,p,l,c){return s(),n("div",null,[...e[0]||(e[0]=[t(`<h1 id="dependabot-maintenance" tabindex="-1">Dependabot maintenance <a class="header-anchor" href="#dependabot-maintenance" aria-label="Permalink to “Dependabot maintenance”">​</a></h1><p>As of <strong>2026-07-24</strong>, production WordPress is <strong>6.7.4</strong>.</p><p>Dependabot opens pull requests when npm or Composer dependencies can be updated, and (when security updates are enabled) when a known vulnerability has a fix. Version-update behaviour is configured in <a href="../.github/dependabot.yml"><code>.github/dependabot.yml</code></a>. Security-fix PRs are a separate GitHub setting — confirm it is on for this repo under <a href="https://github.com/bcgov/bcew-monorepo/settings/security_analysis" target="_blank" rel="noreferrer">Settings → Code security</a> (<strong>Dependabot security updates</strong>).</p><p>It keeps up to <strong>3 open PRs per ecosystem</strong> (npm and Composer). When you merge or close one, Dependabot can open the next. Reviewers are <code>@bcgov/digital-engagement-solutions-custom-web</code> (first available).</p><h2 id="wordpress-and-dependabot" tabindex="-1">WordPress and Dependabot <a class="header-anchor" href="#wordpress-and-dependabot" aria-label="Permalink to “WordPress and Dependabot”">​</a></h2><p>Production runs <strong>WordPress 6.7.4</strong>. Shared <code>@wordpress/*</code> package versions are pinned in <a href="../pnpm-workspace.yaml"><code>pnpm-workspace.yaml</code></a> (<code>catalog:</code> entries use <code>wp-6.7</code> tags). Those packages must stay compatible with that core.</p><p>Dependabot may open a PR that bumps a catalog package (or another dependency) to a version built for a newer WordPress. Merging that would put the monorepo on packages that do not match the core we run. If CI fails for that reason, or the package changelog/release notes require a newer WordPress, defer the update.</p><h2 id="handling-prs" tabindex="-1">Handling PRs <a class="header-anchor" href="#handling-prs" aria-label="Permalink to “Handling PRs”">​</a></h2><ol><li>Open Dependabot PRs (<code>author:dependabot</code>) and <a href="https://github.com/bcgov/bcew-monorepo/security/dependabot" target="_blank" rel="noreferrer">security alerts</a>. Do critical/high security first.</li><li>CI green and compatible with WP 6.7.4 → merge.</li><li>CI red, or the bump needs a newer WordPress → defer.</li></ol><h2 id="can-t-merge-defer" tabindex="-1">Can&#39;t merge? Defer <a class="header-anchor" href="#can-t-merge-defer" aria-label="Permalink to “Can&#39;t merge? Defer”">​</a></h2><ol><li><p>Close the PR.</p></li><li><p>Open an issue (what failed, why, what unblocks it). Example:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Dependabot deferred: @wordpress/block-editor</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Dependabot tried to bump to v14.0.0 but this requires WordPress 6.8+.</span></span>
<span class="line"><span>Production is on 6.7.4.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Unblocks when: production WordPress upgrades to 6.8.</span></span></code></pre></div></li><li><p>Add an <code>ignore</code> in <code>.github/dependabot.yml</code>:</p></li></ol><div class="language-yaml"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">ignore</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">dependency-name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;@wordpress/block-editor&quot;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # Deferred: #123 — needs WP 6.8, production is 6.7.4</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    versions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;14.0.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><ol><li>When the issue can be resolved, resolve it, remove that <code>ignore</code>, then close the issue.</li></ol><p>See also: <a href="./package-management">Package management</a>, <a href="./ci-cd">CI/CD</a>.</p>`,14)])])}const b=a(i,[["render",o]]);export{g as __pageData,b as default};
